// Clean domain string to standard domain configuration
function normalizeDomain(rawDomain: string) {
  const d = (rawDomain || '').toLowerCase().trim();
  if (d.includes('cyber') || d.includes('security')) {
    return { id: 'cybersecurity', code: 'CYBER', name: 'Cybersecurity' };
  }
  if (d.includes('ai') || d.includes('ml') || d.includes('machine') || d.includes('learning')) {
    return { id: 'ai-ml', code: 'AIML', name: 'AI / ML' };
  }
  if (d.includes('defen') || d.includes('defence') || d.includes('defense') || d.includes('military')) {
    return { id: 'defense', code: 'DEF', name: 'Defense' };
  }
  if (d.includes('crisis') || d.includes('emergency') || d.includes('disaster')) {
    return { id: 'crisis-tech', code: 'CRISIS', name: 'Crisis Tech & Emergency Response' };
  }
  if (d.includes('ed') || d.includes('tech') || d.includes('smart learning') || d.includes('learn')) {
    return { id: 'edtech', code: 'EDT', name: 'EdTech & Smart Learning' };
  }
  return { id: 'open-innovation', code: 'OPEN', name: 'Open Innovation' };
}

// Parse helper
function parseCSVLine(line: string): string[] {
  const values: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }
  values.push(current.trim());
  return values;
}

// Parse all real teams from the Google Sheet
export function parseRealTeamsFromSheet(): TeamRecord[] {
  const lines = RAW_REGISTRATION_CSV.trim().split('\n');
  const teams: TeamRecord[] = [];
  
  // Skip header
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const cols = parseCSVLine(line);
    if (cols.length < 7) continue;

    const teamNum = i;
    const padNum = String(teamNum).padStart(3, '0');
    const teamId = `HH26-TEAM-${padNum}`;

    const timestamp = cols[0] || new Date().toISOString();
    const teamNameRaw = cols[1] || `Team ${teamNum}`;
    const domainRaw = cols[2] || 'Open Innovation';
    const domain = normalizeDomain(domainRaw);

    const leadFirstName = (cols[3] || '').trim();
    const leadLastName = (cols[4] || '').trim();
    const leadName = `${leadFirstName} ${leadLastName}`.trim() || 'Team Lead';
    const leadPhone = (cols[5] || '').trim();
    const leadEmail = (cols[6] || '').trim().toLowerCase();
    const college = (cols[7] || 'Shree Swaminarayan Institute of Technology (SSIT)').trim();

    // Members parsing
    const members = [];
    // Lead is member 1
    members.push({
      name: leadName,
      email: leadEmail,
      role: 'Lead' as const,
      phone: leadPhone,
      collegeName: college,
    });

    // Member 2 (cols 11, 12, 13, 14)
    if (cols[11] && cols[11] !== 'N/A' && cols[11] !== 'No' && cols[11] !== 'na') {
      members.push({
        name: cols[11].trim(),
        email: (cols[12] || `${leadFirstName.toLowerCase()}_m2@hackhertz.in`).trim().toLowerCase(),
        role: 'Member' as const,
        phone: cols[13]?.trim() || '',
        collegeName: (cols[14] || college).trim(),
      });
    }

    // Member 3 (cols 16, 17, 18, 19)
    if (cols[16] && cols[16] !== 'N/A' && cols[16] !== 'No' && cols[16] !== 'na') {
      members.push({
        name: cols[16].trim(),
        email: (cols[17] || `${leadFirstName.toLowerCase()}_m3@hackhertz.in`).trim().toLowerCase(),
        role: 'Member' as const,
        phone: cols[18]?.trim() || '',
        collegeName: (cols[19] || college).trim(),
      });
    }

    // Member 4 (cols 21, 22, 23, 24)
    if (cols[21] && cols[21] !== 'N/A' && cols[21] !== 'No' && cols[21] !== 'na') {
      members.push({
        name: cols[21].trim(),
        email: (cols[22] || `${leadFirstName.toLowerCase()}_m4@hackhertz.in`).trim().toLowerCase(),
        role: 'Member' as const,
        phone: cols[23]?.trim() || '',
        collegeName: (cols[24] || college).trim(),
      });
    }

    // Generate unique access code
    const accessCode = generateAccessCode(domain.code, teamNum);

    teams.push({
      teamId,
      teamNumber: teamNum,
      teamName: teamNameRaw.trim(),
      domainId: domain.id,
      domainName: domain.name,
      collegeName: college,
      accessCode,
      teamLead: {
        name: leadName,
        email: leadEmail,
        phone: leadPhone,
      },
      members,
      hasUnlocked: teamNum <= 2,
      unlockedAt: teamNum <= 2 ? new Date().toISOString() : null,
      createdAt: timestamp,
      updatedAt: new Date().toISOString(),
    });
  }

  return teams;
}
